/// <summary>
/// This class is the entry point for requests to be handled by process logic
/// </summary>
class TFMProcessHandler extends TFMInputHandler
{



}

Method.Source:
/// <summary>
/// Runs the process logic
/// </summary>
public void run()
{
    TFMProcess      process;
    TFMProcessID    processId;
    //Find the relevant process, and execute.
    process = TFMProcessProvider::GetAllProcessesImpl().getProcess(request.ContentType(), TFMProcessVersion::newestVersion(request.ContentType(), true));

    if (!process)
    {
        return;
    }

    processId = process.parmProcessName();
    request.makeLogEntry('Using process ' + processId);


    responseElement = process.runProcess(request);


    /*if (classIdGet(responseElement) == classNum(TFMPostResponseData))
    {
        TFMProcessProvider::instance().invalidateProvider();
    }*/
}

/// <summary>
/// Gets the resulting buffer if any.
/// </summary>
/// <returns>A table buffer</returns>
public Common getResultTable()
{
    Common ret = null;


    return ret;
}
